    "strings"
)

func count_words(text string) map[string]int {
    counts := map[string]int{}
    for _, word := range strings.Fields(text) {
        counts[word]++
    }
    return counts
}

func main() {
    for word, n := range count_words("one fish two fish red fish blue fish") {
        if n > 1 || len(word) > 11 {
            fmt.Println(word, n)
        }
    }
}
